"""Storage reports never confuse generated bytes with original RAW storage."""

from pathlib import Path

import pytest

from gomoveshift.pipeline.photos.night_inventory import inventory_project

PROJECT = "a" * 64


def setup(tmp_path):
    source = tmp_path / "source.linear"
    source.mkdir()
    (source / "manifest.json").write_bytes(b"{}")
    (source / "sky_sum.npy").write_bytes(b"1234")
    (source / "unrelated.NEF").write_bytes(b"x" * 1000)
    workspace = tmp_path / "projects"
    project = workspace / PROJECT
    project.mkdir(parents=True)
    row = {
        "id": PROJECT,
        "status": "failed",
        "items": [{"source": str(source), "output": None}, {"source": str(source), "output": None}],
    }
    return row, workspace, project


def test_unique_linear_bytes_and_generated_attempts_are_separate(tmp_path):
    row, workspace, project = setup(tmp_path)
    stale = project / ("0-" + "b" * 32)
    stale.mkdir()
    (stale / "master.tif").write_bytes(b"1234567")
    result = inventory_project(row, workspace)
    assert result["source_linear_bytes"] == 6
    assert result["source_raw_bytes"] is None
    assert result["generated_bytes"] == 7
    assert result["cleanup_candidates"] == [
        {"path": str(stale), "bytes": 7, "reason": "Unreferenced incomplete attempt; review only."}
    ]
    assert stale.exists()


def test_retention_proposal_names_dependencies_and_never_authorizes_deletion(tmp_path):
    row, workspace, project = setup(tmp_path)
    stale = project / ("0-" + "b" * 32)
    stale.mkdir()
    (stale / "partial.tif").write_bytes(b"12345")
    selected = project / ("1-" + "c" * 32)
    selected.mkdir()
    (selected / "receipt.json").write_text("{}")
    row["items"][0]["output"] = str(selected)

    proposal = inventory_project(row, workspace)["retention_proposal"]

    assert proposal["mode"] == "review_only"
    assert proposal["deletion_authorized"] is False
    assert proposal["candidate_count"] == 1
    assert proposal["reclaimable_bytes"] == 5
    assert proposal["candidates"][0]["path"] == str(stale.resolve())
    protected = {item["path"]: item["reason"] for item in proposal["protected"]}
    assert "current project output" in protected[str(selected.resolve())].lower()
    assert "source" in protected[str(Path(row["items"][0]["source"]).resolve())].lower()


def test_current_outputs_and_crash_receipts_are_protected(tmp_path):
    row, workspace, project = setup(tmp_path)
    selected = project / ("0-" + "b" * 32)
    selected.mkdir()
    row["items"][0]["output"] = str(selected)
    crash = project / ("1-" + "c" * 32)
    crash.mkdir()
    (crash / "receipt.json").write_bytes(b"{}")
    report = inventory_project(row, workspace)
    assert report["cleanup_candidates"] == []
    assert str(selected) in report["protected_outputs"]
    assert str(crash) in report["protected_outputs"]
    assert row["items"][0]["source"] in report["protected_outputs"]


def test_active_project_never_offers_inflight_attempt(tmp_path):
    row, workspace, project = setup(tmp_path)
    row["status"] = "running"
    (project / ("0-" + "b" * 32)).mkdir()
    assert inventory_project(row, workspace)["cleanup_candidates"] == []


def test_symlinks_are_not_traversed_or_counted(tmp_path):
    row, workspace, project = setup(tmp_path)
    outside = tmp_path / "outside"
    outside.mkdir()
    (outside / "large").write_bytes(b"x" * 100)
    (project / ("0-" + "b" * 32)).symlink_to(outside, target_is_directory=True)
    (Path(row["items"][0]["source"]) / "ground.npy").symlink_to(outside / "large")
    report = inventory_project(row, workspace)
    assert report["source_linear_bytes"] == 6
    assert report["generated_bytes"] == 0
    assert report["cleanup_candidates"] == []
    assert len(report["warnings"]) >= 2


def test_traversal_identifier_is_rejected(tmp_path):
    row, workspace, _ = setup(tmp_path)
    row["id"] = "../source.linear"
    with pytest.raises(ValueError, match="identifier"):
        inventory_project(row, workspace)


def test_attempt_containing_source_or_selected_file_is_protected(tmp_path):
    row, workspace, project = setup(tmp_path)
    attempt = project / ("0-" + "b" * 32)
    attempt.mkdir()
    nested_source = attempt / "source.linear"
    nested_source.mkdir()
    (nested_source / "manifest.json").write_bytes(b"{}")
    row["items"][0]["source"] = str(nested_source)
    assert inventory_project(row, workspace)["cleanup_candidates"] == []


def test_source_stored_inside_attempt_is_not_generated_storage(tmp_path):
    row, workspace, project = setup(tmp_path)
    attempt = project / ("0-" + "b" * 32)
    attempt.mkdir()
    nested = attempt / "source.linear"
    nested.mkdir()
    (nested / "manifest.json").write_bytes(b"{}")
    row["items"][0]["source"] = str(nested)
    assert inventory_project(row, workspace)["generated_bytes"] == 0


def test_pending_preview_receipt_protects_recoverable_master(tmp_path):
    row, workspace, project = setup(tmp_path)
    attempt = project / ("0-" + "b" * 32)
    attempt.mkdir()
    (attempt / "preview-pending.json").write_text("{}")
    assert inventory_project(row, workspace)["cleanup_candidates"] == []


def test_typed_product_inventory_separates_raw_linear_and_generated_bytes(tmp_path):
    raw = tmp_path / "card" / "light.NEF"
    raw.parent.mkdir()
    raw.write_bytes(b"r" * 11)
    linear = tmp_path / "card" / "stack.linear"
    linear.mkdir()
    (linear / "manifest.json").write_bytes(b"{}")
    workspace = tmp_path / "typed-projects"
    attempt = workspace / PROJECT / ("0-best_stills-" + "b" * 32)
    attempt.mkdir(parents=True)
    (attempt / "master.tif").write_bytes(b"m" * 7)
    (attempt / "product-receipt.json").write_bytes(b"{}")
    row = {
        "id": PROJECT,
        "schema": 2,
        "kind": "night_products",
        "status": "complete",
        "inputs": {
            "lights": [{"path": str(raw)}],
            "darks": [],
            "linear": [{"path": str(linear)}],
        },
        "tasks": [{"status": "complete", "output": str(attempt)}],
    }

    report = inventory_project(row, workspace)

    assert report["source_raw_bytes"] == 11
    assert report["source_linear_bytes"] == 2
    assert report["generated_bytes"] > 7
    assert str(attempt) in report["protected_outputs"]
    assert report["cleanup_candidates"] == []


def test_private_keeper_exports_are_counted_and_protected(tmp_path):
    workspace = tmp_path / "typed-projects"
    exports = workspace / PROJECT / "exports" / ("e" * 64)
    exports.mkdir(parents=True)
    selected = exports / "selected.jpg"
    selected.write_bytes(b"keeper")
    receipt = exports / "export-receipt.json"
    receipt.write_bytes(b"{}")
    row = {
        "id": PROJECT,
        "schema": 2,
        "kind": "night_products",
        "status": "complete",
        "inputs": {"lights": [], "darks": [], "linear": []},
        "tasks": [],
        "private_exports": [
            {
                "path": f"exports/{'e' * 64}/selected.jpg",
                "receipt": f"exports/{'e' * 64}/export-receipt.json",
            }
        ],
    }

    report = inventory_project(row, workspace)

    assert report["generated_bytes"] == len(b"keeper{}")
    assert str(selected.resolve()) in report["protected_outputs"]
    assert str(receipt.resolve()) in report["protected_outputs"]
    assert not any("Unrecognized" in warning for warning in report["warnings"])
